import{_ as n,o as a,c as e,ag as i}from"./chunks/framework.DUTPmUpA.js";const p="/_assets/dngijaZ.DB00kS6Q.png",E=JSON.parse('{"title":"Использование свойств модификатора во всплывающих подсказках","description":"","frontmatter":{"title":"Использование свойств модификатора во всплывающих подсказках","author":"DankBud","steamId":"76561198157673452","date":"05.12.2021"},"headers":[],"relativePath":"abilities/modifier-properties-in-tooltips.md","filePath":"abilities/modifier-properties-in-tooltips.md"}'),l={name:"abilities/modifier-properties-in-tooltips.md"};function t(r,s,o,d,c,h){return a(),e("div",null,[...s[0]||(s[0]=[i('<p>в модификатора во всплывающих подсказках</p><p>Каждый раз, когда вы видите всплывающую подсказку модификатора, использующую нестатический номер, она получает свое значение из одного из <a href="https://moddota.com/api/#!/vscripts/modifierfunction" target="_blank" rel="noreferrer"><code>MODIFIER_PROPERTY_</code></a> этого модификатора.</p><p>несколько примеров: <img src="'+p+`" alt="img"></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;DOTA_Tooltip_modifier_fountain_aura_buff_Description&quot;				&quot;Heals %dMODIFIER_PROPERTY_HEALTH_REGEN_PERCENTAGE%%% HP and %dMODIFIER_PROPERTY_MANA_REGEN_TOTAL_PERCENTAGE%%% mana per second.&quot;</span></span>
<span class="line"><span>\`\`\`![img](/images/external/bzU8GAF.png)\`\`\`</span></span>
<span class="line"><span>&quot;DOTA_Tooltip_modifier_smoke_of_deceit_Description&quot;	&quot;Invisible, moving %dMODIFIER_PROPERTY_MOVESPEED_BONUS_PERCENTAGE%%% faster, and hidden from the minimap. Attacking or moving within %dMODIFIER_PROPERTY_TOOLTIP% range of an enemy hero or tower will break the invisibility.&quot;</span></span>
<span class="line"><span>\`\`\`![img](/images/external/Xy0hTsD.png)\`\`\`</span></span>
<span class="line"><span>&quot;DOTA_Tooltip_modifier_tower_aura_bonus_Description&quot;    &quot;Armor increased by %dMODIFIER_PROPERTY_PHYSICAL_ARMOR_BONUS% and health regeneration by %dMODIFIER_PROPERTY_HEALTH_REGEN_CONSTANT%.&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>и еще примерно 560 примеров в файле assets_english.txt от Valve.</p><p>Как видите, все эти числа не записываются в описание модификатора вручную, они динамически извлекаются из модификатора.</p><h2 id="почему-это-полезно" tabindex="-1">Почему это полезно? <a class="header-anchor" href="#почему-это-полезно" aria-label="Permalink to &quot;Почему это полезно?&quot;">​</a></h2><p>Потому что, если вы вручную записываете числа во всплывающую подсказку, то каждый раз, когда вы меняете число в способности, вам придется не забывать обновлять каждую связанную всплывающую подсказку, и, не говоря уже о хлопотах, вы обязательно что-то пропустите.</p><p>Используя динамическую подсказку, вам нужно изменить число только в одном месте, и оно обновится повсюду. И вы можете изменить возвращаемый номер в своем скрипте во время игры.</p><h2 id="как-это-сделать" tabindex="-1">Как это сделать <a class="header-anchor" href="#как-это-сделать" aria-label="Permalink to &quot;Как это сделать&quot;">​</a></h2><p>Во-первых, обратите внимание, что это работает только с модификаторами Lua и встроенными модификаторами Valve. Это невозможно сделать с помощью модификаторов, управляемых данными.</p><p>Каждый раз, когда вы используете свойство модификатора в модификаторе lua, значение <code>return</code>, которое вы используете, будет доступно для использования во всплывающей подсказке описания модификатора.</p><p>В вашем скрипте модификатора:</p><div class="language-lua vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> modifier_example</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">DeclareFunctions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">	return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">		MODIFIER_PROPERTY_PREATTACK_BONUS_DAMAGE,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	}</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">end</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> modifier_example</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">GetModifierPreAttack_BonusDamage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">	return</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">end</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\`\`\`В вашем \`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">addon_</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;language&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">txt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\`:\`\`\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">json</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;DOTA_Tooltip_modifier_example_Description&quot; &quot;Granting %dMODIFIER_PROPERTY_PREATTACK_BONUS_DAMAGE% bonus damage!&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>В результате появится всплывающая подсказка: <strong><code>Granting 100 bonus damage!</code></strong>.</p><p>В подсказке знак процента <code>%</code> окружает <code>MODIFIER_PROPERTY_</code>, чтобы пометить его как текст, который будет заменен значением свойства-модификатора. Если содержимое между % не соответствует формату, это не сработает.</p><h2 id="формат" tabindex="-1">Формат <a class="header-anchor" href="#формат" aria-label="Permalink to &quot;Формат&quot;">​</a></h2><p><code>%&lt;-&gt;&lt;number&gt;&lt;d|f&gt;MODIFIER_PROPERTY_%</code></p><p>Фрагмент из assets_english.txt:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// substitution for modifier tooltips</span></span>
<span class="line"><span>// %dMODIFIER_PROPERTY_MAGICAL_RESISTANCE_BONUS% - &#39;d&#39; prints the value returned by the function as an integer</span></span>
<span class="line"><span>// &#39;d&#39; for integer</span></span>
<span class="line"><span>// &#39;f&#39; for float</span></span>
<span class="line"><span>// optional &#39;-&#39; to not abs() the values</span></span>
<span class="line"><span>// optional number to specify the number of decimals to print after a float</span></span>
<span class="line"><span>// eg: %-2fMODIFIER_PROPERTY_BASEDAMAGEOUTGOING_PERCENTAGE%</span></span>
<span class="line"><span>// use %% to draw a percentage sign</span></span>
<span class="line"><span>test</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>Первое, что необходимо, — это <code>d</code> для целого числа (целого числа) или <code>f</code> для float (числа с плавающей запятой). Обратите внимание, что здесь учитывается регистр, они должны быть строчными. И один из них обязателен, если вы попытаетесь его пропустить, не получится.</p><p><code>%d...%</code><code>%f...%</code></p><p>Далее следует имя свойства модификатора, убедитесь, что нет пустого места.</p><p><code>%dMODIFIER_PROPERTY_ATTACKSPEED_BONUS_CONSTANT%</code><code>%fMODIFIER_PROPERTY_TOOLTIP%</code></p><p>Вот и все, что вам нужно для отображения всплывающей подсказки.</p><p>Но есть еще 2 варианта, которые вы можете использовать.</p><p>По умолчанию возвращаемое число будет абсолютным. Это означает, что даже если вы вернете отрицательное число, во всплывающей подсказке оно будет положительным. Поставив знак тире/минус <code>-</code> перед d/f, вы сделаете его не абс() числом, поэтому оно может быть отрицательным.</p><p><code>%-dMODIFIER_PROPERTY_COOLDOWN_REDUCTION_CONSTANT%</code><code>%-fMODIFIER_PROPERTY_HEALTH_REGEN_CONSTANT%</code> А с помощью числа с плавающей запятой вы можете добавить число перед <code>f</code>, чтобы выбрать, сколько десятичных знаков отображать (по умолчанию 1).</p><p><code>%-2fMODIFIER_PROPERTY_MANA_REGEN_CONSTANT%</code><code>%3fMODIFIER_PROPERTY_BASE_ATTACK_TIME_CONSTANT%</code></p><p>и, наконец, если вы хотите написать знак процента <code>%</code> во всплывающей подсказке модификатора, вы просто помещаете 2 <code>%%</code> рядом друг с другом в любом месте всплывающей подсказки.</p><p><code>&quot;This is a percentage sign: %%&quot;</code></p><p><code>&quot;Gaining %dMODIFIER_PROPERTY_MOVESPEED_BONUS_PERCENTAGE%%% bonus movement speed&quot;</code></p><h2 id="modifier-property-tooltip" tabindex="-1">MODIFIER_PROPERTY_TOOLTIP <a class="header-anchor" href="#modifier-property-tooltip" aria-label="Permalink to &quot;MODIFIER_PROPERTY_TOOLTIP&quot;">​</a></h2><p>Я оставлю здесь особое примечание для MODIFIER_PROPERTY_TOOLTIP и MODIFIER_PROPERTY_TOOLTIP2. Эти свойства-модификаторы не выполняют никакой функциональной функции, они существуют только для отображения произвольного числа в вашей всплывающей подсказке.</p><p>Простым примером может быть:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lua</span></span>
<span class="line"><span>function modifier_example:DeclareFunctions()</span></span>
<span class="line"><span>	return {</span></span>
<span class="line"><span>		MODIFIER_PROPERTY_TOOLTIP,</span></span>
<span class="line"><span>		MODIFIER_PROPERTY_TOOLTIP2,</span></span>
<span class="line"><span>	}</span></span>
<span class="line"><span>end</span></span>
<span class="line"><span></span></span>
<span class="line"><span>function modifier_example:OnTooltip()</span></span>
<span class="line"><span>	return self:GetStackCount()</span></span>
<span class="line"><span>end</span></span>
<span class="line"><span>function modifier_example:OnTooltip2()</span></span>
<span class="line"><span>	return self.number_of_killed_units</span></span>
<span class="line"><span>end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><h2 id="мои-property-всегда-показывает-0" tabindex="-1">Мой %property% всегда показывает 0 ?? <a class="header-anchor" href="#мои-property-всегда-показывает-0" aria-label="Permalink to &quot;Мой %property% всегда показывает 0 ??&quot;">​</a></h2><p>Если у вас возникла эта проблема, то возвращаемое значение, вероятно, будет видно только на сервере, а не на клиенте. Инструкции см. в этом руководстве: <a href="/abilities/server-to-client">Sending Server values to the Client</a>.</p>`,38)])])}const _=n(l,[["render",t]]);export{E as __pageData,_ as default};
